-- ============================================
-- LUMA — Thème 5 : MOYEN 1/3 x4 — Une visite chez le médecin complète
-- ============================================


update scenarios set content = '{"characters": {"doctor": "le médecin"}, "start_node": "n1", "nodes": {"n1": {"speaker": "doctor", "text": "Good afternoon, I see this is your first visit here. Any medical history I should know about?", "text_fr": "Bon après-midi, je vois que c''est votre première visite ici. Des antécédents médicaux que je devrais connaître ?", "choices": [{"text": "I have mild asthma, but it''s well controlled with an inhaler.", "text_fr": "J''ai un asthme léger, mais c''est bien contrôlé avec un inhalateur.", "next": "n2"}, {"text": "Nothing significant, I''m generally quite healthy.", "text_fr": "Rien de significatif, je suis généralement en bonne santé.", "next": "n2b"}]}, "n2": {"speaker": "doctor", "text": "Good to know. Are you currently taking any medications?", "text_fr": "Bon à savoir. Vous prenez actuellement des médicaments ?", "choices": [{"text": "Just the inhaler when needed, nothing daily.", "text_fr": "Juste l''inhalateur au besoin, rien de quotidien.", "next": "n3"}]}, "n2b": {"speaker": "doctor", "text": "Great. Any allergies I should be aware of?", "text_fr": "Super. Des allergies que je devrais connaître ?", "choices": [{"text": "I''m allergic to penicillin, actually.", "text_fr": "Je suis allergique à la pénicilline, en fait.", "next": "n3"}, {"text": "None that I know of.", "text_fr": "Aucune à ma connaissance.", "next": "n3"}]}, "n3": {"speaker": "doctor", "text": "Noted. So, what brings you in today?", "text_fr": "Noté. Alors, qu''est-ce qui vous amène aujourd''hui ?", "choices": [{"text": "I''ve had persistent headaches for the past two weeks.", "text_fr": "J''ai des maux de tête persistants depuis deux semaines.", "next": "n4"}, {"text": "I''ve been feeling unusually tired lately, even with enough sleep.", "text_fr": "Je me sens anormalement fatigué dernièrement, même avec assez de sommeil.", "next": "n4b"}]}, "n4": {"speaker": "doctor", "text": "How would you describe the headaches — sharp, dull, throbbing?", "text_fr": "Comment décririez-vous les maux de tête — aigus, sourds, pulsatiles ?", "choices": [{"text": "Mostly a dull pressure, especially in the afternoon.", "text_fr": "Surtout une pression sourde, surtout l''après-midi.", "next": "n5"}, {"text": "Sharp, sometimes on just one side of my head.", "text_fr": "Aigus, parfois d''un seul côté de ma tête.", "next": "n5"}]}, "n4b": {"speaker": "doctor", "text": "Have you noticed any changes in your routine — diet, stress, sleep quality?", "text_fr": "Vous avez remarqué des changements dans votre routine — alimentation, stress, qualité du sommeil ?", "choices": [{"text": "Work has been quite stressful lately, actually.", "text_fr": "Le travail a été assez stressant dernièrement, en fait.", "next": "n5"}, {"text": "Not really, everything''s been pretty normal.", "text_fr": "Pas vraiment, tout a été assez normal.", "next": "n5"}]}, "n5": {"speaker": "doctor", "text": "That''s helpful. Let me check your blood pressure and do a quick physical exam.", "text_fr": "C''est utile. Laissez-moi vérifier votre tension et faire un examen physique rapide.", "choices": [{"text": "(Allow the doctor to proceed with the examination.)", "text_fr": "(Laisse le médecin procéder à l''examen.)", "next": "n6"}]}, "n6": {"speaker": "doctor", "text": "Your blood pressure is slightly elevated, but nothing alarming.", "text_fr": "Votre tension est légèrement élevée, mais rien d''alarmant.", "choices": [{"text": "Could that be related to what I''m experiencing?", "text_fr": "Ça pourrait être lié à ce que je ressens ?", "next": "n7"}, {"text": "Is there anything I should be doing differently?", "text_fr": "Il y a quelque chose que je devrais faire différemment ?", "next": "n7"}]}, "n7": {"speaker": "doctor", "text": "It''s possible stress is a contributing factor here. I''d recommend some lifestyle changes first.", "text_fr": "Il est possible que le stress soit un facteur contributif ici. Je recommanderais d''abord des changements de mode de vie.", "choices": [{"text": "What kind of changes would you suggest?", "text_fr": "Quel genre de changements suggéreriez-vous ?", "next": "n8"}]}, "n8": {"speaker": "doctor", "text": "More regular sleep, less caffeine, and maybe some stress management techniques.", "text_fr": "Un sommeil plus régulier, moins de caféine, et peut-être des techniques de gestion du stress.", "choices": [{"text": "That makes sense, I''ll try to make those changes.", "text_fr": "Ça se comprend, je vais essayer de faire ces changements.", "next": "n9"}, {"text": "Should I come back if it doesn''t improve?", "text_fr": "Je devrais revenir si ça ne s''améliore pas ?", "next": "n9b"}]}, "n9": {"speaker": "doctor", "text": "Good. Let''s schedule a follow-up in three weeks to see how you''re doing.", "text_fr": "Bien. Planifions un suivi dans trois semaines pour voir comment vous allez.", "choices": [{"text": "Sounds good, thank you for your time today.", "text_fr": "Ça marche, merci pour votre temps aujourd''hui.", "next": "n10"}]}, "n9b": {"speaker": "doctor", "text": "Absolutely, and if it worsens before then, don''t hesitate to come sooner.", "text_fr": "Absolument, et si ça empire avant, n''hésitez pas à revenir plus tôt.", "choices": [{"text": "Understood, I appreciate the thorough check-up.", "text_fr": "Compris, j''apprécie l''examen approfondi.", "next": "n10"}]}, "n10": {"speaker": "doctor", "text": "Of course, take care of yourself and see you at the follow-up.", "text_fr": "Bien sûr, prenez soin de vous et à bientôt pour le suivi.", "choices": [{"text": "Thank you, doctor. Have a good day.", "text_fr": "Merci, docteur. Bonne journée.", "next": "end_thorough"}]}, "end_thorough": {"speaker": "doctor", "text": "You too — feel better soon!", "text_fr": "Vous aussi — bon rétablissement !", "end": true, "ending_label": "Consultation complète et rassurante 🩺✅"}}}'::jsonb, is_playable = true
where title = 'Une visite chez le médecin complète'
  and theme_id = (select id from scenario_themes where position = 5 and language_id = (select id from languages where code = 'en'));
